<?php
declare(strict_types=1); namespace App\Controllers;
use App\Core\Request; use App\Core\Response; use App\Services\StudentChargeService;
class StudentChargeController { private function out(array $r,int $ok=200):void{if(isset($r['error']))Response::json(['message'=>$r['error'],'duplicates'=>$r['duplicates']??null],$r['status']??422);Response::json($r,$ok);} public function index():void{Response::json((new StudentChargeService())->all($_GET));} public function unpaid():void{Response::json((new StudentChargeService())->unpaid($_GET));} public function show():void{$r=(new StudentChargeService())->one((int)Request::param('id'));if(!$r)Response::json(['message'=>'Charge introuvable'],404);Response::json($r);} public function store():void{$this->out((new StudentChargeService())->create(Request::json()),201);} public function preview():void{$this->out((new StudentChargeService())->preview(Request::json()));} public function bulk():void{$this->out((new StudentChargeService())->bulk(Request::json()),201);} public function update():void{$this->out((new StudentChargeService())->update((int)Request::param('id'),Request::json()));} public function cancel():void{$this->out((new StudentChargeService())->cancel((int)Request::param('id'),Request::json()));} public function history():void{$this->out(['history'=>(new StudentChargeService())->historyFor((int)Request::param('id'))]);}}
